     1→/**
     2→ * FreeWire - 노드 그래프 (노드 + 엣지 컨테이너)
     3→ */
     4→
     5→const { validateNode, validateEdge } = require('./node-spec');
     6→
     7→class Graph {
     8→  constructor(id = 'graph-001') {
     9→    this.id    = id;
    10→    this.nodes = [];   // { id, type, ... }
    11→    this.edges = [];   // { id, from: {nodeId, portId, portType}, to: {nodeId, portId, portType} }
    12→  }
    13→
    14→  // ─── 노드 ─────────────────────────────────────────────────────
    15→  addNode(node) {
    16→    const { valid, errors } = validateNode(node);
    17→    if (!valid) throw new Error(`노드 오류 [${node.id}]: ${errors.join(', ')}`);
    18→    if (this.nodes.find(n => n.id === node.id))
    19→      throw new Error(`중복 노드 id: ${node.id}`);
    20→    this.nodes.push(node);
    21→    return this;
    22→  }
    23→
    24→  removeNode(nodeId) {
    25→    this.nodes  = this.nodes.filter(n => n.id !== nodeId);
    26→    this.edges  = this.edges.filter(e => e.from.nodeId !== nodeId && e.to.nodeId !== nodeId);
    27→    return this;
    28→  }
    29→
    30→  getNode(nodeId) {
    31→    return this.nodes.find(n => n.id === nodeId) || null;
    32→  }
    33→
    34→  // ─── 엣지 ─────────────────────────────────────────────────────
    35→  addEdge(edge) {
    36→    const { valid, errors } = validateEdge(edge, this.nodes);
    37→    if (!valid) throw new Error(`엣지 오류 [${edge.id}]: ${errors.join(', ')}`);
    38→    if (this.edges.find(e => e.id === edge.id))
    39→      throw new Error(`중복 엣지 id: ${edge.id}`);
    40→    this.edges.push(edge);
    41→    return this;
    42→  }
    43→
    44→  removeEdge(edgeId) {
    45→    this.edges = this.edges.filter(e => e.id !== edgeId);
    46→    return this;
    47→  }
    48→
    49→  /** 특정 노드의 입력 엣지 목록 */
    50→  incomingEdges(nodeId) {
    51→    return this.edges.filter(e => e.to.nodeId === nodeId);
    52→  }
    53→
    54→  /** 특정 노드의 출력 엣지 목록 */
    55→  outgoingEdges(nodeId) {
    56→    return this.edges.filter(e => e.from.nodeId === nodeId);
    57→  }
    58→
    59→  // ─── 위상 정렬 (실행 순서 결정) ──────────────────────────────
    60→  topologicalSort() {
    61→    const visited = new Set();
    62→    const onStack = new Set(); // 사이클 감지용
    63→    const order   = [];
    64→
    65→    const visit = (nodeId) => {
    66→      if (visited.has(nodeId)) return;
    67→      if (onStack.has(nodeId)) {
    68→        // 사이클 감지: 이 노드는 건너뜀 (순환 의존)
    69→        return;
    70→      }
    71→      onStack.add(nodeId);
    72→      this.incomingEdges(nodeId).forEach(e => visit(e.from.nodeId));
    73→      onStack.delete(nodeId);
    74→      visited.add(nodeId);
    75→      order.push(nodeId);
    76→    };
    77→
    78→    this.nodes.forEach(n => visit(n.id));
    79→    return order.map(id => this.getNode(id));
    80→  }
    81→
    82→  // ─── 직렬화 / 역직렬화 ───────────────────────────────────────
    83→  toJSON() {
    84→    return { id: this.id, nodes: this.nodes, edges: this.edges };
    85→  }
    86→
    87→  static fromJSON(json) {
    88→    const g = new Graph(json.id);
    89→    (json.nodes || []).forEach(n => g.addNode(n));
    90→    (json.edges || []).forEach(e => g.addEdge(e));
    91→    return g;
    92→  }
    93→
    94→  // ─── 통계 ─────────────────────────────────────────────────────
    95→  stats() {
    96→    const typeCount = {};
    97→    this.nodes.forEach(n => {
    98→      typeCount[n.type] = (typeCount[n.type] || 0) + 1;
    99→    });
   100→    return {
   101→      totalNodes: this.nodes.length,
   102→      totalEdges: this.edges.length,
   103→      byType: typeCount,
   104→    };
   105→  }
   106→}
   107→
   108→module.exports = { Graph };
   109→

