     1→/**
     2→ * FreeWire - .free 코드 → HTML/CSS/JS 실행기
     3→ * FreeLang Light 컴파일러 로직을 내장하여 의존성 없이 동작
     4→ */
     5→
     6→class FreeExecutor {
     7→  /**
     8→   * @param {string} freeCode  - GraphCompiler가 생성한 .free 문자열
     9→   * @param {object} graphJson - 원본 그래프 JSON (메타 정보 참조용)
    10→   * @returns {{ html: string, css: string, js: string, stats: object }}
    11→   */
    12→  execute(freeCode, graphJson = {}) {
    13→    const sections = this._parseSections(freeCode);
    14→
    15→    const css  = this._compileStyle(sections.style);
    16→    const js   = this._compileScript(sections.script);
    17→    const html = this._compileMarkup(sections.markup);
    18→
    19→    return {
    20→      html,
    21→      css,
    22→      js,
    23→      stats: {
    24→        htmlBytes: html.length,
    25→        cssBytes:  css.length,
    26→        jsBytes:   js.length,
    27→        sections:  Object.keys(sections).filter(k => sections[k]),
    28→      },
    29→    };
    30→  }
    31→
    32→  // ─── 파서: .free 섹션 분리 ──────────────────────────────────
    33→
    34→  _parseSections(code) {
    35→    const sections = { props: '', style: '', script: '', markup: '' };
    36→    const pattern  = /\b(props|style|script|markup)\s*\{/g;
    37→    let match;
    38→    const positions = [];
    39→
    40→    while ((match = pattern.exec(code)) !== null) {
    41→      positions.push({ type: match[1], start: match.index + match[0].length });
    42→    }
    43→
    44→    positions.forEach((pos, i) => {
    45→      const end   = this._findBlockEnd(code, pos.start - 1);
    46→      const inner = code.slice(pos.start, end).trim();
    47→      sections[pos.type] += '\n' + inner;
    48→    });
    49→
    50→    return sections;
    51→  }
    52→
    53→  _findBlockEnd(code, openBrace) {
    54→    // openBrace 위치에서 '{' 찾기
    55→    let idx = openBrace;
    56→    while (idx < code.length && code[idx] !== '{') idx++;
    57→    let depth = 1;
    58→    idx++;
    59→    while (idx < code.length && depth > 0) {
    60→      if (code[idx] === '{') depth++;
    61→      else if (code[idx] === '}') depth--;
    62→      idx++;
    63→    }
    64→    return idx - 1;
    65→  }
    66→
    67→  // ─── CSS 컴파일 ─────────────────────────────────────────────
    68→
    69→  _compileStyle(styleBlock) {
    70→    if (!styleBlock.trim()) return '';
    71→
    72→    // camelCase → kebab-case
    73→    return styleBlock
    74→      .replace(/([a-z])([A-Z])/g, '$1-$2')
    75→      .toLowerCase()
    76→      .replace(/\s*\n\s*/g, '\n')
    77→      .trim();
    78→  }
    79→
    80→  // ─── JS 컴파일 ──────────────────────────────────────────────
    81→
    82→  _compileScript(scriptBlock) {
    83→    if (!scriptBlock.trim()) return '';
    84→
    85→    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    86→    const output = [];
    87→
    88→    output.push('(function() {');
    89→    output.push('  "use strict";');
    90→    output.push('  var _ctx = {};');
    91→
    92→    lines.forEach(line => {
    93→      // 주석 라인은 그대로
    94→      if (line.startsWith('//')) {
    95→        output.push('  ' + line);
    96→        return;
    97→      }
    98→      // 변수 선언
    99→      if (line.startsWith('let ') || line.startsWith('const ')) {
   100→        output.push('  ' + line);
   101→        const m = line.match(/^(?:let|const)\s+(\w+)\s*=/);
   102→        if (m) output.push(`  _ctx['${m[1]}'] = ${m[1]};`);
   103→        return;
   104→      }
   105→      // 함수 선언
   106→      if (line.startsWith('function ')) {
   107→        output.push('  ' + line);
   108→        return;
   109→      }
   110→      // if/else
   111→      if (line.startsWith('if ') || line.startsWith('if(') ||
   112→          line.startsWith('} else') || line === '}' || line === '{') {
   113→        output.push('  ' + line);
   114→        return;
   115→      }
   116→      // 기타 (map/filter/reduce 결과 등)
   117→      output.push('  ' + line);
   118→    });
   119→
   120→    // DOM 준비 후 state 바인딩
   121→    output.push('  // DOM 이벤트 바인딩');
   122→    output.push('  document.addEventListener("DOMContentLoaded", function() {');
   123→    output.push('    var btns = document.querySelectorAll("button");');
   124→    output.push('    btns.forEach(function(btn) {');
   125→    output.push('      btn.addEventListener("click", function() {');
   126→    output.push('        if (typeof handleClick === "function") handleClick(this);');
   127→    output.push('        if (typeof increment  === "function") increment();');
   128→    output.push('        _updateDOM();');
   129→    output.push('      });');
   130→    output.push('    });');
   131→    output.push('    _updateDOM();');
   132→    output.push('  });');
   133→    output.push('  function _updateDOM() {');
   134→    output.push('    var displays = document.querySelectorAll("[data-bind]");');
   135→    output.push('    displays.forEach(function(el) {');
   136→    output.push('      var key = el.getAttribute("data-bind");');
   137→    output.push('      try { el.textContent = Object.prototype.hasOwnProperty.call(_ctx, key) ? _ctx[key] : ""; } catch(e) {}');
   138→    output.push('    });');
   139→    output.push('  }');
   140→    output.push('})();');
   141→
   142→    return output.join('\n');
   143→  }
   144→
   145→  // ─── HTML 컴파일 ────────────────────────────────────────────
   146→
   147→  _compileMarkup(markupBlock) {
   148→    if (!markupBlock.trim()) return '';
   149→
   150→    let html = markupBlock
   151→      // 중첩 markup { } 제거
   152→      .replace(/markup\s*\{/g, '')
   153→      .replace(/^\s*\}\s*$/gm, '')
   154→      // {{변수}} → <span data-bind="변수">변수</span>
   155→      .replace(/\{\{(\w+)\}\}/g, '<span data-bind="$1">$1</span>')
   156→      // 빈 줄 정리
   157→      .replace(/\n{3,}/g, '\n\n')
   158→      .trim();
   159→
   160→    return html;
   161→  }
   162→}
   163→
   164→module.exports = { FreeExecutor };
   165→

