     1→/**
     2→ * FreeWire — AI Graph Generator
     3→ *
     4→ * Claude API → 노드 그래프 JSON 동적 생성
     5→ *
     6→ * 사용자의 자연어 설명을 받아서
     7→ * FreeWire 노드 + 와이어 구조를 생성한다.
     8→ *
     9→ * 키워드 룩업이 아니다.
    10→ * 의미를 이해하고 그래프를 만든다.
    11→ */
    12→
    13→'use strict';
    14→
    15→const Anthropic = require('@anthropic-ai/sdk');
    16→
    17→// ─── 노드 타입 레퍼런스 (Claude에게 알려줄 스펙) ─────────────────
    18→
    19→const NODE_SPEC = `
    20→# FreeWire 노드 스펙
    21→
    22→## 노드 타입
    23→
    24→### component 노드 (UI 요소)
    25→- button:    { type:"component", subtype:"button",    props:{label:"텍스트", variant:"primary|secondary|ghost|danger"} }
    26→- text:      { type:"component", subtype:"text",      props:{content:"텍스트", tag:"h1|h2|h3|p|span|label"} }
    27→- input:     { type:"component", subtype:"input",     props:{placeholder:"힌트", type:"text|email|password|number"} }
    28→- card:      { type:"component", subtype:"card",      props:{title:"제목"} }
    29→- container: { type:"component", subtype:"container", props:{direction:"row|column", gap:"8px"} }
    30→- image:     { type:"component", subtype:"image",     props:{src:"url", alt:"설명"} }
    31→- badge:     { type:"component", subtype:"badge",     props:{text:"배지", color:"blue|green|red|yellow"} }
    32→
    33→### data 노드 (데이터 흐름)
    34→- state:     { type:"data", subtype:"state",   props:{name:"변수명", initial:"초기값"} }
    35→- const:     { type:"data", subtype:"const",   props:{value:"값", valueType:"string|number|boolean"} }
    36→- array:     { type:"data", subtype:"array",   props:{items:"[]"} }
    37→- props:     { type:"data", subtype:"props",   props:{schema:"{}"} }
    38→
    39→### logic 노드 (제어 흐름)
    40→- handler:   { type:"logic", subtype:"handler",   props:{name:"함수명"} }
    41→- setState:  { type:"logic", subtype:"setState",  props:{stateName:"변수명", value:"새값"} }
    42→- ifelse:    { type:"logic", subtype:"ifelse",    props:{condition:"조건식"} }
    43→
    44→## 와이어 구조
    45→{ from: "노드ID", fromPort: 0, to: "노드ID", toPort: 0 }
    46→
    47→## 포트 컨벤션
    48→- button  inputs[0]=props, inputs[1]=onClick(핸들러 연결)
    49→- text    inputs[0]=content(데이터 바인딩)
    50→- input   inputs[0]=value, inputs[1]=onChange
    51→- card    inputs[0..n]=children
    52→- container inputs[0..n]=children
    53→- handler → button: { from:handlerId, fromPort:0, to:buttonId, toPort:1 }
    54→- state   → text:   { from:stateId,   fromPort:0, to:textId,   toPort:0 }
    55→`;
    56→
    57→const SYSTEM_PROMPT = `당신은 FreeWire 노드 그래프 생성기입니다.
    58→사용자의 UI 설명을 읽고 FreeWire 노드 그래프 JSON을 생성합니다.
    59→
    60→${NODE_SPEC}
    61→
    62→## 응답 형식 (반드시 순수 JSON만 반환, 설명 텍스트 없이)
    63→
    64→{
    65→  "label": "그래프 이름",
    66→  "nodes": [
    67→    { "id": "n1", "type": "component", "subtype": "button", "label": "버튼[로그인]", "props": {"label":"로그인","variant":"primary"} },
    68→    ...
    69→  ],
    70→  "edges": [
    71→    { "id": "e1", "from": "n2", "fromPort": 0, "to": "n1", "toPort": 1 },
    72→    ...
    73→  ]
    74→}
    75→
    76→## 규칙
    77→1. 노드 ID는 "n1", "n2" 형식
    78→2. 와이어 ID는 "e1", "e2" 형식
    79→3. 버튼이 있으면 반드시 handler 노드와 연결 (toPort: 1)
    80→4. state 노드가 있으면 반드시 text 노드에 바인딩 (fromPort:0, toPort:0)
    81→5. 관련 노드들은 card나 container로 묶기
    82→6. label은 "타입[이름]" 형식 (예: "버튼[로그인]", "상태[count]")
    83→7. 사용자 요청을 정확히 반영 — 없다고 한 것은 만들지 않기
    84→8. 순수 JSON만 반환 (코드블록, 설명 없음)`;
    85→
    86→// ─── 메인 함수 ──────────────────────────────────────────────────
    87→
    88→async function aiGenerateGraph(prompt, apiKey) {
    89→  const key = apiKey || process.env.ANTHROPIC_API_KEY;
    90→  if (!key) throw new Error('API 키가 없습니다. ANTHROPIC_API_KEY 환경변수 또는 요청 body.apiKey 필요');
    91→
    92→  const client = new Anthropic({ apiKey: key });
    93→
    94→  const message = await client.messages.create({
    95→    model: 'claude-haiku-4-5-20251001',  // 빠르고 저렴
    96→    max_tokens: 2048,
    97→    system: SYSTEM_PROMPT,
    98→    messages: [
    99→      { role: 'user', content: prompt }
   100→    ],
   101→  });
   102→
   103→  const raw = message.content[0]?.text ?? '';
   104→  const graph = parseGraphJSON(raw);
   105→
   106→  // 레이아웃 계산
   107→  graph.nodes = applyLayout(graph.nodes);
   108→
   109→  return {
   110→    graph,
   111→    label:      graph.label,
   112→    nodeCount:  graph.nodes.length,
   113→    edgeCount:  graph.edges.length,
   114→    model:      message.model,
   115→    usage:      message.usage,
   116→    rawPrompt:  prompt,
   117→  };
   118→}
   119→
   120→// ─── JSON 파싱 (방어적) ─────────────────────────────────────────
   121→
   122→function parseGraphJSON(raw) {
   123→  // 코드블록 제거
   124→  let text = raw.trim()
   125→    .replace(/^```json\s*/i, '')
   126→    .replace(/^```\s*/i, '')
   127→    .replace(/\s*```$/, '')
   128→    .trim();
   129→
   130→  // JSON 시작 위치 찾기
   131→  const start = text.indexOf('{');
   132→  const end   = text.lastIndexOf('}');
   133→  if (start === -1 || end === -1) throw new Error('JSON 응답을 찾을 수 없습니다');
   134→
   135→  text = text.slice(start, end + 1);
   136→
   137→  let graph;
   138→  try {
   139→    graph = JSON.parse(text);
   140→  } catch (e) {
   141→    throw new Error('JSON 파싱 실패: ' + e.message + '\n원본: ' + text.slice(0, 200));
   142→  }
   143→
   144→  // 필수 필드 보장
   145→  if (!graph.nodes) graph.nodes = [];
   146→  if (!graph.edges) graph.edges = [];
   147→  if (!graph.label) graph.label = 'AI 생성 그래프';
   148→
   149→  // edge id 보장
   150→  graph.edges = graph.edges.map((e, i) => ({
   151→    id: e.id ?? `e${i + 1}`,
   152→    from:      e.from      ?? e.fromNode,
   153→    fromPort:  e.fromPort  ?? 0,
   154→    to:        e.to        ?? e.toNode,
   155→    toPort:    e.toPort    ?? 0,
   156→  }));
   157→
   158→  return graph;
   159→}
   160→
   161→// ─── 자동 레이아웃 ──────────────────────────────────────────────
   162→
   163→function applyLayout(nodes) {
   164→  const W = 200, H = 130, GAP_X = 70, GAP_Y = 24;
   165→
   166→  // type 순서: data → logic → component
   167→  const ORDER = { data: 0, logic: 1, component: 2 };
   168→  const cols   = { data: [], logic: [], component: [] };
   169→
   170→  for (const n of nodes) {
   171→    const col = cols[n.type] ?? cols.component;
   172→    col.push(n);
   173→  }
   174→
   175→  let x = 80;
   176→  const result = [];
   177→
   178→  for (const [typeName, col] of Object.entries(cols)) {
   179→    if (col.length === 0) continue;
   180→    col.forEach((n, i) => {
   181→      result.push({ ...n, position: { x, y: 80 + i * (H + GAP_Y) } });
   182→    });
   183→    x += W + GAP_X;
   184→  }
   185→
   186→  return result;
   187→}
   188→
   189→module.exports = { aiGenerateGraph };
   190→

