     1→/**
     2→ * FreeWire - 공통 노드 스펙 (포트 타입, 검증 규칙)
     3→ */
     4→
     5→const PORT_TYPES = {
     6→  COMPONENT: 'component',
     7→  DATA:      'data',
     8→  LOGIC:     'logic',
     9→  EVENT:     'event',
    10→  ANY:       'any',
    11→};
    12→
    13→const NODE_TYPES = {
    14→  COMPONENT: 'component',
    15→  DATA:      'data',
    16→  LOGIC:     'logic',
    17→  AI:        'ai',
    18→};
    19→
    20→/** 포트 타입 호환성 매트릭스 */
    21→const PORT_COMPAT = {
    22→  component: ['component', 'any'],
    23→  data:      ['data', 'any'],
    24→  logic:     ['logic', 'any'],
    25→  event:     ['event', 'any'],
    26→  any:       ['component', 'data', 'logic', 'event', 'any'],
    27→};
    28→
    29→/**
    30→ * 두 포트가 연결 가능한지 검사
    31→ * @param {string} outputType - 출력 포트 타입
    32→ * @param {string} inputType  - 입력 포트 타입
    33→ * @returns {boolean}
    34→ */
    35→function isCompatible(outputType, inputType) {
    36→  const allowed = PORT_COMPAT[outputType] || [];
    37→  return allowed.includes(inputType);
    38→}
    39→
    40→/**
    41→ * 노드 JSON 기본 유효성 검사
    42→ * @param {object} node
    43→ * @returns {{ valid: boolean, errors: string[] }}
    44→ */
    45→function validateNode(node) {
    46→  const errors = [];
    47→
    48→  if (!node.id || typeof node.id !== 'string')
    49→    errors.push('id: 문자열 필수');
    50→
    51→  if (!node.type || !Object.values(NODE_TYPES).includes(node.type))
    52→    errors.push(`type: ${Object.values(NODE_TYPES).join('|')} 중 하나여야 함`);
    53→
    54→  if (!Array.isArray(node.inputs))
    55→    errors.push('inputs: 배열 필수');
    56→
    57→  if (!Array.isArray(node.outputs))
    58→    errors.push('outputs: 배열 필수');
    59→
    60→  if (typeof node.props !== 'object' || node.props === null)
    61→    errors.push('props: 객체 필수');
    62→
    63→  return { valid: errors.length === 0, errors };
    64→}
    65→
    66→/**
    67→ * 엣지(연결선) 유효성 검사
    68→ * @param {object} edge   { id, from: {nodeId, portId, portType}, to: {nodeId, portId, portType} }
    69→ * @param {object[]} nodes - 전체 노드 목록
    70→ * @returns {{ valid: boolean, errors: string[] }}
    71→ */
    72→function validateEdge(edge, nodes) {
    73→  const errors = [];
    74→
    75→  if (!edge.id) errors.push('edge.id 필수');
    76→  if (!edge.from?.nodeId) errors.push('edge.from.nodeId 필수');
    77→  if (!edge.to?.nodeId)   errors.push('edge.to.nodeId 필수');
    78→
    79→  if (edge.from?.nodeId === edge.to?.nodeId)
    80→    errors.push('자기 자신에게 연결 불가');
    81→
    82→  if (edge.from?.portType && edge.to?.portType) {
    83→    if (!isCompatible(edge.from.portType, edge.to.portType))
    84→      errors.push(`포트 타입 불일치: ${edge.from.portType} → ${edge.to.portType}`);
    85→  }
    86→
    87→  const fromNode = nodes?.find(n => n.id === edge.from?.nodeId);
    88→  const toNode   = nodes?.find(n => n.id === edge.to?.nodeId);
    89→  if (!fromNode) errors.push(`출발 노드 없음: ${edge.from?.nodeId}`);
    90→  if (!toNode)   errors.push(`도착 노드 없음: ${edge.to?.nodeId}`);
    91→
    92→  return { valid: errors.length === 0, errors };
    93→}
    94→
    95→module.exports = { PORT_TYPES, NODE_TYPES, PORT_COMPAT, isCompatible, validateNode, validateEdge };
    96→

