     1→/**
     2→ * FreeWire - Graph → FreeLang Light 컴파일러
     3→ * 노드 그래프 JSON → 완성된 .free 파일 문자열 생성
     4→ */
     5→
     6→const { Graph }              = require('../core/graph');
     7→const { toFreelangMarkup }   = require('../core/nodes/component');
     8→const { toFreelangCode: dataToCode }  = require('../core/nodes/data');
     9→const { toFreelangCode: logicToCode } = require('../core/nodes/logic');
    10→
    11→class GraphCompiler {
    12→  constructor() {
    13→    this.errors   = [];
    14→    this.warnings = [];
    15→  }
    16→
    17→  /**
    18→   * Graph 인스턴스 또는 JSON → .free 파일 문자열
    19→   * @param {Graph|object} input
    20→   * @returns {{ code: string, errors: string[], warnings: string[] }}
    21→   */
    22→  compile(input) {
    23→    this.errors   = [];
    24→    this.warnings = [];
    25→
    26→    const graph = input instanceof Graph ? input : Graph.fromJSON(input);
    27→    const sorted = graph.topologicalSort();
    28→
    29→    const propsNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'props');
    30→    const stateNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'state');
    31→    const constNodes     = sorted.filter(n => n.type === 'data' && !['props','state'].includes(n.dataType));
    32→    const logicNodes     = sorted.filter(n => n.type === 'logic');
    33→    const componentNodes = sorted.filter(n => n.type === 'component');
    34→
    35→    if (componentNodes.length === 0) {
    36→      this.warnings.push('component 노드가 없습니다. markup 블록이 비어 있습니다.');
    37→    }
    38→
    39→    // 컴포넌트 이름: 그래프 id 또는 첫 component 이름
    40→    const compName = this._resolveComponentName(graph, componentNodes);
    41→
    42→    const sections = [];
    43→
    44→    // 1) component 헤더
    45→    sections.push(`component ${compName} {`);
    46→
    47→    // 2) props 블록
    48→    const propsBlock = this._buildPropsBlock(propsNodes);
    49→    if (propsBlock) sections.push(propsBlock);
    50→
    51→    // 3) style 블록 (component props에서 수집)
    52→    const styleBlock = this._buildStyleBlock(componentNodes);
    53→    if (styleBlock) sections.push(styleBlock);
    54→
    55→    // 4) script 블록 (state + const + logic)
    56→    const scriptBlock = this._buildScriptBlock(stateNodes, constNodes, logicNodes, graph);
    57→    if (scriptBlock) sections.push(scriptBlock);
    58→
    59→    // 5) markup 블록
    60→    const markupBlock = this._buildMarkupBlock(componentNodes, graph);
    61→    sections.push(markupBlock);
    62→
    63→    sections.push('}');
    64→
    65→    return {
    66→      code:     sections.join('\n\n'),
    67→      errors:   this.errors,
    68→      warnings: this.warnings,
    69→    };
    70→  }
    71→
    72→  // ─── 내부 빌더 ──────────────────────────────────────────────
    73→
    74→  _resolveComponentName(graph, componentNodes) {
    75→    if (componentNodes.length > 0 && componentNodes[0].props?.name) {
    76→      return componentNodes[0].props.name;
    77→    }
    78→    return graph.id.replace(/[^a-zA-Z0-9]/g, '_') || 'MyComponent';
    79→  }
    80→
    81→  _buildPropsBlock(propsNodes) {
    82→    if (propsNodes.length === 0) return null;
    83→    const lines = propsNodes.map(n => {
    84→      if (!n.props) {
    85→        this.warnings.push(`props 노드 [${n.id}]에 props 객체 없음 - 건너뜀`);
    86→        return null;
    87→      }
    88→      const { name, value, required } = n.props;
    89→      if (!name) {
    90→        this.warnings.push(`props 노드 [${n.id}]에 name 없음 - 건너뜀`);
    91→        return null;
    92→      }
    93→      const req = required ? '' : `= ${JSON.stringify(value ?? null)}`;
    94→      return `  ${name}: ${n.dataType ?? 'any'} ${req}`.trimEnd() + ';';
    95→    }).filter(Boolean);
    96→    return `  props {\n${lines.join('\n')}\n  }`;
    97→  }
    98→
    99→  _buildStyleBlock(componentNodes) {
   100→    const styleLines = [];
   101→    componentNodes.forEach(n => {
   102→      const p = n.props;
   103→      const selector = `.${n.componentType}`;
   104→      const rules = [];
   105→
   106→      if (p.color)        rules.push(`color: ${p.color}`);
   107→      if (p.background)   rules.push(`background: ${p.background}`);
   108→      if (p.padding)      rules.push(`padding: ${p.padding}`);
   109→      if (p.gap)          rules.push(`gap: ${p.gap}`);
   110→      if (p.fontSize)     rules.push(`font-size: ${p.fontSize}`);
   111→      if (p.borderRadius) rules.push(`border-radius: ${p.borderRadius}`);
   112→      if (p.direction && n.componentType === 'container') {
   113→        rules.push(`display: flex`);
   114→        rules.push(`flex-direction: ${p.direction}`);
   115→      }
   116→
   117→      if (rules.length > 0) {
   118→        styleLines.push(`  ${selector} {`);
   119→        rules.forEach(r => styleLines.push(`    ${r};`));
   120→        styleLines.push(`  }`);
   121→      }
   122→    });
   123→
   124→    if (styleLines.length === 0) return null;
   125→    return `  style {\n${styleLines.join('\n')}\n  }`;
   126→  }
   127→
   128→  _buildScriptBlock(stateNodes, constNodes, logicNodes, graph) {
   129→    const lines = [];
   130→
   131→    // 상수
   132→    constNodes.forEach(n => {
   133→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
   134→    });
   135→
   136→    // 상태
   137→    stateNodes.forEach(n => {
   138→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
   139→      lines.push(`  function set_${n.props.name}(v) { ${n.props.name} = v; }`);
   140→    });
   141→
   142→    // 로직 노드 (연결 정보 포함)
   143→    logicNodes.forEach(n => {
   144→      const code = this._logicNodeToScript(n, graph);
   145→      if (code) lines.push(code);
   146→    });
   147→
   148→    if (lines.length === 0) return null;
   149→    return `  script {\n${lines.join('\n')}\n  }`;
   150→  }
   151→
   152→  _logicNodeToScript(node, graph) {
   153→    const { logicType, props } = node;
   154→
   155→    // 입력 연결에서 실제 값/노드 id 추론
   156→    const inEdges = graph.incomingEdges(node.id);
   157→    const getConnected = (portId) => {
   158→      const e = inEdges.find(e => e.to.portId === portId);
   159→      return e ? e.from.nodeId : null;
   160→    };
   161→
   162→    switch (logicType) {
   163→      case 'if': {
   164→        const cond = props.condition || getConnected('condition') || 'true';
   165→        return [
   166→          `  if (${cond}) {`,
   167→          `    // then: ${getConnected('then') || '연결 없음'}`,
   168→          `  } else {`,
   169→          `    // else: ${getConnected('else') || '연결 없음'}`,
   170→          `  }`,
   171→        ].join('\n');
   172→      }
   173→      case 'function':
   174→        return [
   175→          `  function ${props.name}(${(props.params || []).join(', ')}) {`,
   176→          `    ${props.body || 'return null;'}`,
   177→          `  }`,
   178→        ].join('\n');
   179→      case 'map':
   180→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).map(function(${props.itemName}) { return ${props.expression}; });`;
   181→      case 'filter':
   182→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).filter(function(${props.itemName}) { return ${props.condition}; });`;
   183→      case 'reduce':
   184→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).reduce(function(${props.accumName}, ${props.itemName}) { return ${props.expression}; }, ${props.initial});`;
   185→      case 'loop':
